def evaluate(expr: str) -> float:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append(('OP', c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    # Parser using recursive descent
    # Grammar:
    # expr   -> term (('+' | '-') term)*
    # term   -> factor (('*' | '/') factor)*
    # factor -> ('+' | '-') factor | atom
    # atom   -> NUM | '(' expr ')'

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        left = parse_term()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        left = parse_factor()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('*', '/'):
            op = consume()[1]
            right = parse_factor()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right
        return left

    def parse_factor():
        tok = peek()
        if tok and tok[0] == 'OP' and tok[1] in ('+', '-'):
            op = consume()[1]
            val = parse_factor()
            return -val if op == '-' else val
        return parse_atom()

    def parse_atom():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'NUM':
            consume()
            return float(tok[1])
        if tok[0] == 'OP' and tok[1] == '(':
            consume()
            val = parse_expr()
            if peek() and peek()[0] == 'OP' and peek()[1] == ')':
                consume()
            else:
                raise ValueError("Missing closing parenthesis")
            return val
        raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected token after expression")
    return result
